import{_ as t,o as r,c as i,a2 as o}from"./chunks/framework.BWuWLRhz.js";const p=JSON.parse('{"title":"General","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/settings/general.md","filePath":"user-guide/settings/general.md","lastUpdated":1787287369000}'),a={name:"user-guide/settings/general.md"};function n(s,e,l,h,d,c){return r(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h1><p>Six tabs: <strong>System</strong>, <strong>Quick Search Window</strong>, <strong>Full Search Window</strong>, <strong>Preview</strong>, <strong>Quick Navigation</strong>, and <strong>Preview &amp; Thumbnails</strong>.</p><h2 id="system" tabindex="-1">System <a class="header-anchor" href="#system" aria-label="Permalink to &quot;System&quot;">​</a></h2><ul><li><strong>Start Lertaro with Windows</strong> — checkbox, launches Lertaro at sign-in.</li><li><strong>Auto check for updates on startup</strong> — checkbox.</li><li><strong>Auto silent update when a new version is detected</strong> — checkbox, only enabled while the check above is on; downloads and installs updates in the background without prompting.</li><li><strong>Enable hardware acceleration</strong> — checkbox, on by default. Turning it off forces the quick search window to render in software instead of using Direct3D — this works around NVIDIA Advanced Optimus refusing to hot-switch GPUs while Lertaro is running (only the quick window is affected, not the whole app). Requires restarting Lertaro to take effect.</li><li><strong>Hide tray icon</strong> — checkbox, off by default. Applies immediately, no restart needed. The same menu the tray icon&#39;s right-click shows is always available from the <a href="./../hotkeys.html#search-box-logo-icon">Quick window&#39;s own logo</a> regardless of this setting, so hiding the tray icon never strands you without a way back into Settings or Exit.</li><li><strong>Enable Everything IPC emulation</strong> — checkbox, off by default. Allows third-party tools that integrate with or depend on Everything (such as Directory Opus, Total Commander, and Flow Launcher) to seamlessly perform searches and calculate folder sizes using Lertaro&#39;s in-memory index.</li><li><strong>Enable fuzzy matching</strong> — checkbox, on by default. With fuzzy matching on, a bare search term matches as long as its characters occur in order anywhere in the name; turning this off requires a bare term to appear as a contiguous substring instead (<code>abc</code> no longer matches <code>a-b-c</code>) — see <a href="./../search-syntax.html#fuzzy-matching-default">Search Syntax</a> for what does and doesn&#39;t change. Applies immediately, no restart needed.</li><li><strong>Global query token prefix</strong> — text box (1 character max, default <code>:</code>). Sets the lead prefix character used to split query token expressions at the trailing position of the search box. Dynamic path filtering and custom filter providers also configure their prefix characters under <strong>Settings → Plugins → CoreExtensions</strong>.</li><li><strong>Log level</strong> — dropdown: Error / Warn / Info (default) / Debug. Controls verbosity across the App, Service, and Hook logs (see <a href="./service-status.html">Service Status</a>).</li><li><strong>Interface language</strong> — dropdown, populated from every installed translation provider (built-in languages plus any a plugin adds).</li></ul><p>Theme selection moved to its own <a href="./appearance.html">Appearance</a> section — see that page for the theme picker and the &quot;follow system light/dark setting&quot; option.</p><h2 id="quick-search-window" tabindex="-1">Quick Search Window <a class="header-anchor" href="#quick-search-window" aria-label="Permalink to &quot;Quick Search Window&quot;">​</a></h2><p>Covers both the quick search bar&#39;s appearance and how its search results are prioritized.</p><p><strong>Search Bar Layout</strong> — customizes the size and on-screen position of the quick search bar:</p><ul><li><strong>Search Bar Width (px)</strong> — range 300–1200px, default 570px.</li><li><strong>Search Bar Height (px)</strong> — range 45–120px, default 60px. This one number also drives the result row&#39;s icon size, name/path font size, and row height (<code>height / 60</code>), so a taller search bar scales the whole result list up with it, always keeping the same proportions between icon and text.</li><li><strong>Show clock in search box</strong> — checkbox, off by default. While the search box is empty, replaces the usual &quot;Type to search...&quot; placeholder text with the current date, day of week, and time instead. Disappears the moment you start typing, same as the placeholder it replaces. Quick window only — the inline window always keeps its normal placeholder, even with this on.</li><li><strong>Reopen as full window on repeat hotkey</strong> — checkbox, off by default. Normally, pressing the toggle hotkey again while the quick window is already open just hides it; turning this on makes the second press switch to the full window instead (carrying over whatever query you&#39;d already typed), rather than closing anything.</li><li><strong>Lock position</strong> — checkbox, off by default. Stops the quick window being dragged, so a stray press can&#39;t nudge it off the spot you put it on. Right-clicking the logo still resets its position, and <strong>Reset Layout Settings</strong> below clears the lock along with everything else.</li><li><strong>Reset Layout Settings</strong> button — restores all five settings above to their defaults.</li></ul><p>Right-clicking the <a href="./../hotkeys.html#search-box-logo-icon">quick window&#39;s logo</a> resets just its on-screen position (not size), re-centering it the same way it centers on first launch.</p><p><strong>Result Type Priority</strong> — the same up/down-arrow (or drag-to-reorder) list used for <a href="#quick-navigation">Quick Navigation</a> below: move a result type (Applications, Settings, File Filters, any third-party plugin&#39;s own searchable items, or the built-in &quot;Files&quot; entry) up or down to make it always outrank the types below it in the quick window&#39;s results, regardless of which one actually matched the query text better. History and Favorites always come first and aren&#39;t part of this list.</p><p>Each type can also have its own single-character <strong>trigger</strong> (optional, one text box per row): typing that character as the very first thing in the quick window shows only that type&#39;s results, hiding everything else — see <a href="./../search-syntax.html#result-type-trigger">Search Syntax</a> for examples. Typing just the trigger with nothing after it yet shows a &quot;keep typing to search X only&quot; prompt instead of &quot;No Search Results&quot;. Pick a character you&#39;d never normally start a real search with, since it&#39;s reserved once a type is assigned it — a punctuation character (e.g. <code>;</code>) works more reliably than a plain space, since a lone space with nothing typed after it is treated the same as an empty search box and won&#39;t show that prompt.</p><h2 id="full-search-window" tabindex="-1">Full Search Window <a class="header-anchor" href="#full-search-window" aria-label="Permalink to &quot;Full Search Window&quot;">​</a></h2><p>Sets the default size of the full/main search window (the larger window you get from the taskbar or Start Menu shortcut, as opposed to the quick popup — see <a href="./../getting-started.html#the-three-windows">Getting Started</a>):</p><ul><li><strong>Window Width (px)</strong> — range 640–2000px, default 854px.</li><li><strong>Window Height (px)</strong> — range 400–1400px, default 480px. The minimums match the window&#39;s own resize floor, so a configured value is never silently overridden by the window itself.</li><li><strong>Reset Search Window Settings</strong> button.</li><li><strong>Only allow one full search window</strong> — checkbox, off by default. When off, you can open several independent full windows. When on, opening the full window again activates an existing one instead of creating another; a query carried over from Quick window&#39;s <strong>Show More</strong> replaces that window&#39;s query.</li></ul><p>Dragging the window&#39;s edge to resize it manually is remembered automatically — the next time you open the window (or open a new one), it comes back at whatever size you last left it at, and this page&#39;s fields update to match. Resizing while maximized doesn&#39;t overwrite the remembered size; only resizing in the normal (non-maximized) state does.</p><p>The full window does not prepend Favorites or History recall entries to its result list. Those personalized recall results remain in the Quick and inline windows; the full window keeps the normal relevance order from active search providers.</p><p><strong>Results Grid Column Order</strong> — the same reorder list used elsewhere in Settings (see <a href="./favorites.html">Favorites</a>): move a results-grid column (Name, Path, Date Modified, or any plugin-provided column) left or right. Only affects the grid/table results layout — there are no columns to reorder in the compact list layout.</p><p><strong>Sidebar Filter Order</strong> — same mechanic, for the order the sidebar&#39;s filter groups (Type, Date Modified, and any plugin-added groups) appear in.</p><p>While a full search is running, each sidebar filter shows a live count of matches in the current query. Counts update as results stream in and reset when the query changes; they are not affected by which sidebar filter is currently selected. The sidebar width follows its widest filter label and count, so labels remain visible without wrapping.</p><p><strong>Actions Menu Section Order</strong> — same mechanic, for the order the sections of the <a href="./../actions-and-preview.html#actions-menu">actions menu</a> appear in: the built-in actions group, plus one section per plugin that contributes actions there (e.g. Custom Actions, or the Windows shell right-click menu). A section not yet in this list falls back to its natural position (built-in first, then plugin sections in whatever order they were contributed).</p><p>Clicking a results-grid column header cycles through three states: ascending, descending, then a third click resets it back to the default relevance-ranked order (the header&#39;s sort arrow disappears). This is remembered only for as long as Lertaro keeps running — quitting the app (not just closing the window) resets sorting back to the default the next time you open it, unlike the column/sidebar order above which is saved permanently.</p><h2 id="preview" tabindex="-1">Preview <a class="header-anchor" href="#preview" aria-label="Permalink to &quot;Preview&quot;">​</a></h2><ul><li><strong>Preview Width (px)</strong> — range 250–900px.</li><li><strong>Preview Height (px)</strong> — range 250–1200px, default sized so the pane isn&#39;t overly tall on a typical display.</li><li><strong>Reset Preview Window Settings</strong> button.</li></ul><p>The preview window ignores the current result count — it&#39;s a fixed size, not a size that grows with content. See <a href="./../actions-and-preview.html">Actions Menu &amp; Preview</a> for how the pane is positioned.</p><h2 id="quick-navigation" tabindex="-1">Quick Navigation <a class="header-anchor" href="#quick-navigation" aria-label="Permalink to &quot;Quick Navigation&quot;">​</a></h2><p>Sets the order the <a href="./../hotkeys.html#quick-navigation-mouse">Quick Navigation</a> menu&#39;s root-level sections appear in — one section per contributing provider (e.g. Favorites/History/configured folders, Total Commander&#39;s Directory Hotlist, Directory Opus&#39;s Favorites, a plugin&#39;s own quick-nav entries), each labeled with its own header.</p><p><strong>Provider Order</strong> — the same up/down-arrow (or drag-to-reorder) list used elsewhere in Settings (see <a href="./favorites.html">Favorites</a>): move a provider up or down to change where its section lands relative to the others. Only providers whose plugin component is currently enabled are listed here — one disabled under <a href="./plugins.html">Plugins</a> never becomes a menu candidate in the first place, so there&#39;s nothing to order for it.</p><h2 id="preview-thumbnails" tabindex="-1">Preview &amp; Thumbnails <a class="header-anchor" href="#preview-thumbnails" aria-label="Permalink to &quot;Preview &amp; Thumbnails&quot;">​</a></h2><p>Two independent priority-order lists, each deciding which provider gets first refusal for its own job — normally decided purely by each provider&#39;s own fixed, built-in priority, with no way to change that short of disabling a provider entirely.</p><p><strong>File Preview Provider Order</strong> — for <a href="./../actions-and-preview.html#quicklook-preview">file preview providers</a> (for example, the <a href="./../actions-and-preview.html#external-preview-via-quicklook-optional">QuickLook Bridge</a> plugin sets its own priority above every built-in previewer). The same up/down-arrow (or drag-to-reorder) list used elsewhere in Settings (see <a href="./favorites.html">Favorites</a>): move a provider up to make it always win over the ones below it, regardless of its own built-in priority. Only providers whose plugin component is currently enabled are listed here — one disabled under <a href="./plugins.html">Plugins</a> would never actually preview anything anyway.</p><p><strong>Thumbnail Provider Order</strong> — same mechanic, for the icons/thumbnails shown next to results in the search list itself (as opposed to the preview pane) — most relevant once more than one plugin implements a custom thumbnail provider, since only one built-in provider exists today.</p>',32)])])}const g=t(a,[["render",n]]);export{p as __pageData,g as default};
